import type { TranslationBlock } from './types'

const blocks: TranslationBlock[] = [
{ type: 'heading', zh: '中山经', en: 'Classic of the Central Mountains' },
    { type: 'para', zh: '《中山经》薄山山系的第一座山，叫甘枣山。共水从这里发源，向西流入黄河。山上多杻树，山下有一种草，名叫籜，长着葵菜一样的茎、杏树一样的叶子，开黄色的花，结荚果，吃了它可以治疗目盲。山中有一种野兽，形状像𤠢鼠，额头上有花纹，名字叫㔮，吃了它的肉可以治好颈肿病。', en: 'The Central Mountains begin at Mount Ganzao, head of the Thin Mountains. The Gong River flows west into the Yellow River. It has many oak trees above and a grass below called tui, with sunflower stems, apricot leaves, yellow flowers and pod fruit—it cures blindness. A beast called the nao, shaped like a rat with a patterned forehead—eating it cures goiter.' },
    { type: 'para', zh: '再往东二十里，有座山叫历儿山，山上多橿树，还有很多櫔树，这种树长着方形的茎、圆形的叶子，开黄色的花，花上有细毛，果实像枣子，吃了它能让人记忆力好、不健忘。', en: 'Twenty li east is Mount Li\'er, with many zhen trees and li trees—these have square stems, round leaves, yellow flowers and bristles, with fruit like dates; eating it prevents forgetfulness.' },
    { type: 'para', zh: '再往东十五里，有座山叫渠猪山，山上多竹子。渠猪水从这里发源，向南流入黄河。水中有很多豪鱼，形状像鲔鱼，长着红色的嘴、红色的尾巴和红色的鳍，吃了它可以治好白癣。', en: 'Fifteen li east is Mount Quzhu, with much bamboo. The Quzhu River flows south into the Yellow River. It contains many hao fish, shaped like wei fish with red beaks, red tails and red feathers—they cure white ringworm.' },
    { type: 'para', zh: '再往东三十五里，有座山叫葱聋山，山中有很多大山谷，产大量白垩，还有黑、青、黄三色垩。', en: 'Thirty-five li east is Mount Conglong, with many large valleys, much white chalk, and black, blue and yellow chalk.' },
    { type: 'para', zh: '再往东十五里，有座山叫涹山，山上多红铜，山的北面多铁。', en: 'Fifteen li east is Mount Wo, with much red copper above and iron on its north face.' },
    { type: 'para', zh: '再往东七十里，有座山叫脱扈山。山中有一种草，名叫植楮，叶子像葵叶，开红色的花，结荚果，果实像棕榈荚，吃了它可以治抑郁症、让人不做噩梦。', en: 'Seventy li east is Mount Tuohu. A grass called zhichu, shaped like sunflower leaves with red flowers and pod fruit like brown palm pods—it cures melancholy and eating it prevents nightmares.' },
    { type: 'para', zh: '再往东二十里，有座山叫金星山，山上多天婴，形状像龙骨，可以治痤疮。', en: 'Twenty li east is Mount Jinxing, with much tianying that looks like dragon bones—it cures acne.' },
    { type: 'para', zh: '再往东七十里，有座山叫泰威山，山中有一个山谷叫枭谷，谷中多铁。', en: 'Seventy li east is Mount Taiwei, with a valley called Xiao Gu containing much iron.' },
    { type: 'para', zh: '再往东十五里，有座山叫橿谷山，山中多红铜。', en: 'Fifteen li east is Mount Zhengu, with much red copper.' },
    { type: 'para', zh: '再往东一百二十里，有座山叫吴林山，山中多茝草。', en: 'One hundred twenty li east is Mount Wulin, with much jian grass.' },
    { type: 'para', zh: '再往北三十里，有座山叫牛首山。山中有一种草，名叫鬼草，叶子像葵叶，茎是红色的，穗子像禾苗，吃了它使人无忧无虑。劳水从这里发源，向西流入潏水。水中多飞鱼，形状像鲫鱼，吃了它可以治痔疮和瘘管。', en: 'Thirty li north is Mount Niushou. A grass called guicao, with sunflower-like leaves and red stems, flowering like grain—eating it prevents worry. The Lao River flows west into the Yu waters, containing many flying fish shaped like crucian carp—eating them cures hemorrhoids and fistula.' },
    { type: 'para', zh: '再往北四十里，有座山叫霍山，山上多构树。山中有一种野兽，形状像野猫，尾巴是白色的，颈上有长毛，名字叫朏朏，养着它可以消除忧愁。', en: 'Forty li north is Mount Huo, with much paper mulberry. A beast called the feifei, shaped like a badger with a white tail and mane—raising it relieves sorrow.' },
    { type: 'para', zh: '再往北五十二里，有座山叫合谷山，山中多薝棘。', en: 'Fifty-two li north is Mount Hegu, with much zhan thorn.' },
    { type: 'para', zh: '再往北三十五里，有座山叫阴山，多磨刀石和带花纹的石头。少水从这里发源，水中多彫棠树，叶子像榆叶但呈方形，果实像红豆，吃了它可以治耳聋。', en: 'Thirty-five li north is Mount Yin, with much whetstone and patterned stone. The Shao River flows from it, containing many diao tang trees with elm-like square leaves and red bean-like fruit—eating them cures deafness.' },
    { type: 'para', zh: '再往东北四百里，有座山叫鼓鐙山，多红铜。山中有一种草，名叫荣草，叶子像柳叶，根部像鸡蛋，吃了它可以治风病。', en: 'Four hundred li northeast is Mount Gudeng, with much red copper. A grass called rongcao, with willow-like leaves and roots like chicken eggs—it cures wind disorders.' },
    { type: 'para', zh: '薄山山系，从甘枣山到鼓鐙山，总共有十五座山，绵延六千六百七十里。历儿山是一座陵冢，祭祀的礼仪是：用牛、羊、猪三牲齐全的祭品（太牢），并悬挂吉玉作为祭品。其余十三座山的祭祀是用一只羊，悬挂用藻玉做的珪，埋入地下但不供奉谷物。藻珪就是藻玉做的珪，下面呈方形，上面尖锐，中间穿孔并镶嵌金饰。', en: 'In all, the Thin Mountains from Mount Ganzao to Mount Gudeng comprise fifteen peaks spanning 6,670 li. Li\'er is the tomb—for its sacrifice, the full set of livestock is used and the infant is suspended with auspicious jade. The remaining thirteen use a ram, with the infant suspended using an algae gui, buried without grain. The algae gui is algae jade—square at the bottom, pointed at the top, pierced in the middle and inlaid with gold.' },
    { type: 'heading', zh: '中次二经', en: 'Central Mountains II' },
    { type: 'para', zh: '中次二经记载的济山山系，第一座山叫煇诸山，山上多桑树，野兽多是山驴和麋鹿，鸟类多是鶡鸟。', en: 'The second Central Mountains, the Ji Mountains, begin at Mount Huizhu, with much mulberry, white deer as beasts, and he birds as birds.' },
    { type: 'para', zh: '再往西南二百里，有座山叫发视山，山上多金属和玉石，山下多磨刀石和粗磨石。即鱼水从这里发源，向西流入伊水。', en: 'Two hundred li southwest is Mount Fashi, with gold and jade above and whetstones and grindstones below. The Jiyu River flows west into the Yi River.' },
    { type: 'para', zh: '再往西三百里，有座山叫豪山，山上多金属和玉石，但没有花草树木。', en: 'Three hundred li west is Mount Hao, with gold and jade but no plants.' },
    { type: 'para', zh: '再往西三百里，有座山叫鲜山，多金属和玉石，但没有花草树木。鲜水从这里发源，向北流入伊水。水中多鸣蛇，形状像蛇，却长着四只翅膀，叫声像敲击磬石，它一出现，当地就会大旱。', en: 'Three hundred li west is Mount Xian, with gold and jade but no plants. The Xian River flows north into the Yi River, containing many ming snakes—serpents with four wings and a sound like a chime stone; their appearance brings great drought.' },
    { type: 'para', zh: '再往西三百里，有座山叫阳山，多石头，没有花草树木。阳水从这里发源，向北流入伊水。水中多化蛇，长着人的面孔、豺狼的身体，还有鸟的翅膀，像蛇一样爬行，叫声像呵斥呼喊，它一出现，当地就会发大水。', en: 'Three hundred li west is Mount Yang, with much stone and no plants. The Yang River flows north into the Yi River, containing many hua snakes—human-faced, jackal-bodied, with bird wings and serpentine movement, whose cry is like shouting; their appearance brings great floods.' },
    { type: 'para', zh: '再往西二百里，有座山叫昆吾山，山上多红铜。山中有一种野兽，形状像猪，头上长角，叫声像号哭，名字叫蠪蛭，吃了它就不做噩梦。', en: 'Two hundred li west is Mount Kunwu, with much red copper above. A beast called the longzhi, shaped like a pig with horns and a voice like wailing—eating it prevents nightmares.' },
    { type: 'para', zh: '再往西一百二十里，有座山叫葌山。葌水从这里发源，向北流入伊水。山上多金属和玉石，山下多青雄黄。山中有一种树，形状像棠树，叶子是红色的，名叫芒草，能毒死鱼。', en: 'One hundred twenty li west is Mount Jian. The Jian River flows north into the Yi River, with gold and jade above and blue realgar below. A tree called mangcao, shaped like a tang tree with red leaves—it can poison fish.' },
    { type: 'para', zh: '再往西一百五十里，有座山叫独苏山，没有花草树木，但水很多。', en: 'One hundred fifty li west is Mount Dusu, with no plants and much water.' },
    { type: 'para', zh: '再往西一百二十里，有座山叫蔓渠山，山上多金属和玉石，山下多小竹。伊水从这里发源，向东流入洛水。山中有一种野兽，名字叫马腹，长着人的面孔、老虎的身体，叫声像婴儿啼哭，会吃人。', en: 'One hundred twenty li west is Mount Manqu, with gold and jade above and bamboo arrows below. The Yi River flows east into the Luo River. A beast called the mafu, with a human face and tiger body, has a voice like a baby\'s and devours people.' },
    { type: 'para', zh: '济山山系，从煇诸山到蔓渠山，总共有九座山，绵延一千六百七十里。这些山的山神都长着人的面孔、鸟的身体。祭祀时用牲畜作牺牲，再用一块吉玉投入山中，不需要供奉谷物。', en: 'In all, the Ji Mountains from Mount Huizhu to Mount Manqu comprise nine peaks spanning 1,670 li. Their spirits all have human faces and bird bodies. For the sacrifice, fur is used with one beautiful jade, cast without grain.' },
    { type: 'heading', zh: '中次三经', en: 'Central Mountains III' },
    { type: 'para', zh: '中次三经记载的萯山山系，第一座山叫敖岸山，山的南面多㻬琈玉，山的北面多赭石和黄金。神熏池住在这里，这里经常产出美玉。向北可以望见河边的树林，形状像莤草和举草。山中有一种野兽，形状像白鹿，头上长着四只角，名字叫夫诸，它一出现，当地就会发大水。', en: 'The third Central Mountains, the Tai Mountains, begin at Mount Ao\'an, with turou jade on its south face and ochre and gold on its north. The god Xunchi dwells here, and fine jade often emerges from it. To the north, the river forest looks like xi or ju. A beast called the fuzhu, shaped like a white deer with four horns—its appearance brings great floods.' },
    { type: 'para', zh: '再往东十里，有座山叫青要山，这里其实是天帝的秘密都邑。山中多驾鸟。向南可以望见墠渚，那里是大禹的父亲死后化身为黄熊的地方，有很多仆累和蒲卢。神武罗掌管这里，长着人的面孔、豹子的斑纹，腰很细，牙齿洁白，耳朵穿孔佩戴玉制的耳环，叫声像玉石相击的声音。这座山对女子有益。畛水从这里发源，向北流入黄河。山中有一种鸟，名叫鴢，形状像野鸭，身体是青色的，眼睛是红色的，尾巴是红色的，吃了它可以使人多子。山中有一种草，名叫荀草，形状像葌草，茎是方形的，开黄色的花，结红色的果实，根部像藁本的根，吃了它可以使人脸色美丽。', en: 'Ten li east is Mount Qingyao, truly the Emperor\'s secret capital. There are many jia birds. To the south lies Tiantan, where Yu\'s father was transformed, with many puli and pulu. The deity Wuluo manages it—human-faced with leopard markings, a narrow waist and white teeth, with ears pierced by jade rings, whose voice is like ringing jade. This mountain benefits women. The Zhen River flows north into the Yellow River. A bird called the you, shaped like a duck with a blue body, red eyes and red tail—eating it promotes childbearing. A grass called xuncao, shaped like jian grass with square stems, yellow flowers and red fruit, with roots like gaoben—eating it beautifies complexion.' },
    { type: 'para', zh: '再往东十里，有座山叫騩山，山上多优质枣树，山的北面多㻬琈玉。正回水从这里发源，向北流入黄河。水中多飞鱼，形状像猪，身上有红色斑纹，佩戴它就不怕打雷，还可以防御兵器。', en: 'Ten li east is Mount Gui, with fine jade above and turou jade below. The Zhenghui River flows north into the Yellow River, containing many flying fish shaped like pigs with red patterns—wearing them dispels fear of thunder and wards off weapons.' },
    { type: 'para', zh: '再往东四十里，有座山叫宜苏山，山上多金属和玉石，山下多蔓居树。滽滽水从这里发源，向北流入黄河，水中多黄贝。', en: 'Forty li east is Mount Yisu, with gold and jade above and many manju trees below. The Yongyong River flows north into the Yellow River, containing many yellow shells.' },
    { type: 'para', zh: '再往东二十里，有座山叫和山，山上没有花草树木，却多瑶、碧等美玉，这里其实是黄河的九座都邑之一。这座山有五道弯，九条水从这里发源，汇合后向北流入黄河，水中多苍玉。吉神泰逢掌管这里，长着人的身体、老虎的尾巴，喜欢住在萯山的南面，出入时有光亮。泰逢神能兴风作雨。', en: 'Twenty li east is Mount He, with no plants but much jasper, truly the nine capitals of the Yellow River. This mountain has five bends; nine rivers flow from it, joining and flowing north into the Yellow River, containing much blue jade. The auspicious god Taifeng manages it—human-faced with a tiger tail, dwelling on the south face of the Tai Mountains, emerging and entering with light. The Taifeng spirit moves the qi of heaven and earth.' },
    { type: 'para', zh: '萯山山系，从敖岸山到和山，总共有五座山，绵延四百四十里。祭祀的礼仪是：泰逢、熏池、武罗三位神都用剖开的公羊，用吉玉作为祭品。另外两座神用一只公鸡，埋入地下，用稻米作祭品。', en: 'In all, the Tai Mountains from Mount Ao\'an to Mount He comprise five peaks spanning 440 li. For the sacrifice: Taifeng, Xunchi and Wuluo each use a split ram, with the infant using auspicious jade. The two other gods use one rooster buried, with millet for grain.' },
    { type: 'heading', zh: '中次四经', en: 'Central Mountains IV' },
    { type: 'para', zh: '中次四经记载的釐山山系，第一座山叫鹿蹄山，山上多玉，山下多金属。甘水从这里发源，向北流入洛水，水中多泠石。', en: 'The fourth Central Mountains, the Xi Mountains, begin at Mount Luti, with jade above and gold below. The Gan River flows north into the Luo River, containing much ling stone.' },
    { type: 'para', zh: '往西五十里，有座山叫扶猪山，山上多礝石。山中有一种野兽，形状像貉，却长着人的眼睛，名字叫䴦。虢水从这里发源，向北流入洛水，水中多瓀石。', en: 'Fifty li west is Mount Fuzhu, with much ruan stone. A beast called the ying, shaped like a raccoon dog with human eyes. The Guo River flows north into the Luo River, containing much ruan stone.' },
    { type: 'para', zh: '再往西一百二十里，有座山叫釐山，山的南面多玉，山的北面多蒐草。山中有一种野兽，形状像牛，身体是青色的，叫声像婴儿啼哭，会吃人，名字叫犀渠。滽滽水从这里发源，向南流入伊水。山中还有一种野兽，名字叫𤢺，形状像獳犬，身上有鳞，毛像野猪的鬃毛。', en: 'One hundred twenty li west is Mount Xi, with jade on its south face and sou on its north. A beast called the xiqu, shaped like an ox with a blue body and a voice like a baby\'s, devours people. The Yongyong River flows south into the Yi River. A beast called the xiao, shaped like a scaly dog with bristles like a wild boar\'s mane.' },
    { type: 'para', zh: '再往西二百里，有座山叫箕尾山，多构树，多涂石，山上多㻬琈玉。', en: 'Two hundred li west is Mount Jiwei, with much paper mulberry, tu stone, and turou jade above.' },
    { type: 'para', zh: '再往西二百五十里，有座山叫柄山，山上多玉，山下多铜。滔雕水从这里发源，向北流入洛水，水中多羬羊。山中有一种树，形状像樗树，叶子像桐树叶，结荚果，名字叫茇，能毒死鱼。', en: 'Two hundred fifty li west is Mount Bing, with jade above and copper below. The Taodiao River flows north into the Luo River, containing many qian sheep. A tree called ba, shaped like a chinaberry with paulownia-like leaves and pod fruit—it can poison fish.' },
    { type: 'para', zh: '再往西二百里，有座山叫白边山，山上多金属和玉石，山下多青雄黄。', en: 'Two hundred li west is Mount Baibian, with gold and jade above and blue realgar below.' },
    { type: 'para', zh: '再往西二百里，有座山叫熊耳山，山上多漆树，山下多棕榈。浮濠水从这里发源，向西流入洛水，水中多水晶，多人鱼。山中有一种草，形状像紫苏，开红色的花，名叫葶薴，能毒死鱼。', en: 'Two hundred li west is Mount Xiong\'er, with lacquer above and palm below. The Fuhao River flows west into the Luo River, containing much water jade and many human fish. A grass called tingning, shaped like perilla with red flowers—it can poison fish.' },
    { type: 'para', zh: '再往西三百里，有座山叫牡山，山上多带花纹的石头，山下多小竹和䉋竹，野兽多是㸲牛和羬羊，鸟类多是红色的锦鸡。', en: 'Three hundred li west is Mount Mu, with much patterned stone above and bamboo arrows below, zong cattle and qian sheep as beasts, and red pheasants as birds.' },
    { type: 'para', zh: '再往西三百五十里，有座山叫讙举山。雒水从这里发源，向东北流入玄扈水，水中多马肠。这两座山夹在洛水两岸。', en: 'Three hundred fifty li west is Mount Huanju. The Luo River flows northeast into the Xuanyou waters, containing much machang creatures. These two mountains lie between the Luo.' },
    { type: 'para', zh: '釐山山系，从鹿蹄山到玄扈山，总共有九座山，绵延一千六百七十里。这些山的山神都长着人的面孔、野兽的身体。祭祀时用一只白公鸡作牺牲，祈祷但不供奉谷物，用彩色布帛包裹祭品。', en: 'In all, the Xi Mountains from Mount Luti to Mount Xuanyou comprise nine peaks spanning 1,670 li. Their spirits all have human faces and beast bodies. For the sacrifice, a white rooster is used for prayer without grain, dressed in colorful garments.' },
    { type: 'heading', zh: '中次五经', en: 'Central Mountains V' },
    { type: 'para', zh: '中次五经记载的薄山山系，第一座山叫苟牀山，没有花草树木，多奇形怪状的石头。', en: 'The fifth Central Mountains, the Thin Mountains, begin at Mount Gouchuang, with no plants and many strange stones.' },
    { type: 'para', zh: '往东三百里，有座山叫首山，山的北面多构树和柞树，草多是𦬸芫，山的南面多㻬琈玉，树木多槐树。山的北面有个山谷叫机谷，谷中多䲦鸟，形状像猫头鹰，却长着三只眼睛，还有耳朵，叫声像鹿叫，吃了它可以治抑郁症。', en: 'Three hundred li east is Mount Shou, with paper mulberry and oak on its north face, much xuan yuan grass, turou jade on its south face and many scholar trees. A valley on its north face called Ji Gu has many dai birds, shaped like owls with three eyes and ears, whose cry is like lu—eating them cures depression.' },
    { type: 'para', zh: '再往东三百里，有座山叫县劚山，没有花草树木，多带花纹的石头。', en: 'Three hundred li east is Mount Xianchu, with no plants and much patterned stone.' },
    { type: 'para', zh: '再往东三百里，有座山叫葱聋山，没有花草树木，多𢈪石。', en: 'Three hundred li east is Mount Conglong, with no plants and much zhang stone.' },
    { type: 'para', zh: '往东北五百里，有座山叫条谷山，山中多槐树和桐树，草多是芍药和虋冬。', en: 'Five hundred li northeast is Mount Tiaogu, with many scholar trees and paulownia, much peony and men dong grass.' },
    { type: 'para', zh: '再往北十里，有座山叫超山，山的北面多苍玉，山的南面有一口井，冬天有水，夏天干涸。', en: 'Ten li north is Mount Chao, with much blue jade on its north face and a well on its south that has water in winter and dries in summer.' },
    { type: 'para', zh: '再往东五百里，有座山叫成侯山，山上多櫄树，草多是芃草。', en: 'Five hundred li east is Mount Chenghou, with much chun trees above and much peng grass.' },
    { type: 'para', zh: '再往东五百里，有座山叫朝歌山，山谷中多优质白垩。', en: 'Five hundred li east is Mount Chaoge, with much fine chalk in its valley.' },
    { type: 'para', zh: '再往东五百里，有座山叫槐山，山谷中多金属和锡。', en: 'Five hundred li east is Mount Huai, with much gold and tin in its valley.' },
    { type: 'para', zh: '再往东十里，有座山叫历山，山中多槐树，山的南面多玉。', en: 'Ten li east is Mount Li, with many scholar trees and jade on its south face.' },
    { type: 'para', zh: '再往东十里，有座山叫尸山，多苍玉，野兽多是麖鹿。尸水从这里发源，向南流入洛水，水中多美玉。', en: 'Ten li east is Mount Shi, with much blue jade and many mi deer. The Shi River flows south into the Luo waters, containing much beautiful jade.' },
    { type: 'para', zh: '再往东十里，有座山叫良馀山，山上多构树和柞树，没有石头。馀水从山的北面发源，向北流入黄河；乳水从山的南面发源，向东南流入洛水。', en: 'Ten li east is Mount Liangyu, with much paper mulberry and oak above and no stones. The Yu River flows from its north face into the Yellow River; the Ru River flows from its south face southeast into the Luo.' },
    { type: 'para', zh: '再往东南十里，有座山叫蛊尾山，多磨刀石和红铜。龙馀水从这里发源，向东南流入洛水。', en: 'Ten li southeast is Mount Guwei, with much whetstone and red copper. The Longyu River flows southeast into the Luo.' },
    { type: 'para', zh: '再往东北二十里，有座山叫升山，山中多构树、柞树和荆棘，草多是藇蕙和寇脱。黄酸水从这里发源，向北流入黄河，水中多璇玉。', en: 'Twenty li northeast is Mount Sheng, with much paper mulberry, oak and thorns, much yu hui grass and koutuo. The Huang Suan River flows north into the Yellow River, containing much xuan jade.' },
    { type: 'para', zh: '再往东二十里，有座山叫阳虚山，多金属，临近玄扈水。', en: 'Twenty li east is Mount Yangxu, with much gold, overlooking the Xuanyou waters.' },
    { type: 'para', zh: '薄山山系，从苟林山到阳虚山，总共有十六座山，绵延二千九百八十二里。升山是一座陵冢，祭祀的礼仪是：用太牢（牛、羊、猪三牲齐全），用吉玉作祭品。首山是神，祭祀时用稻米、黑色牲畜、太牢祭品和发酵的酒；举行武舞，设置鼓；用一块玉璧作祭品。尸水与天相通，要用肥壮的牲畜祭祀，上面用一只黑狗，下面用一只母鸡，剖开一只母羊，用血祭祀。用吉玉作祭品，用彩色布帛包裹，举行盛宴。', en: 'In all, the Thin Mountains from Mount Goulin to Mount Yangxu comprise sixteen peaks spanning 2,982 li. Sheng is the tomb—for its sacrifice, the full set of livestock is used with the infant in auspicious jade. Shou is the deity—its sacrifice uses millet, black livestock, the full set of vessels and fermented liquor; dancing with drums; one bi for the Infant. Shui water joins heaven—a fat sacrificial animal is used, with a black dog above and a hen below, cutting a ewe to offer blood. The Infant uses auspicious jade with colorful garments, and offerings are made.' },
    { type: 'heading', zh: '中次六经', en: 'Central Mountains VI' },
    { type: 'para', zh: '中次六经记载的縞羝山山系，第一座山叫平逢山，向南可以望见伊水和洛水，向东可以望见穀城山，没有花草树木，没有水，多沙石。山中有一位神，形状像人，却长着两个头，名字叫骄虫，它是螫人的虫，其实是蜜蜂聚居的巢穴。祭祀时用一只公鸡，用来祈福但不要杀掉。', en: 'The sixth Central Mountains, the Gaodi Mountains, begin at Mount Pingfeng, overlooking the Yi and Luo to the south and the Gucheng Mountains to the east, with no plants, no water and much sand and stone. A deity called the jiaochong, shaped like a human with two heads, is the stinging insect—the dwelling place of bees. For its sacrifice, a rooster is used for blessing without killing.' },
    { type: 'para', zh: '往西十里，有座山叫縞羝山，没有花草树木，多金属和玉石。', en: 'Ten li west is Mount Gaodi, with no plants and much gold and jade.' },
    { type: 'para', zh: '再往西十里，有座山叫廆山，山的北面多㻬琈玉。山的北面有个山谷叫雚谷，谷中多柳树和构树。山中有一种鸟，形状像山鸡，尾巴很长，红得像丹火，嘴是青色的，名字叫鴒䳩，叫声像在呼唤自己的名字，吃了它可以治噩梦。交觞水从山的南面发源，向南流入洛水；俞随水从山的北面发源，向北流入穀水。', en: 'Ten li west is Mount Wei, with much turou jade on its north face. A valley called Huangu on its north face has many willows and paper mulberries. A bird called the lingyan, shaped like a pheasant with a long tail, red like cinnabar fire with a blue beak, has a cry like its name—eating it prevents nightmares. The Jiaoshang River flows from its south face into the Luo; the Yusui River flows from its north face into the Gu waters.' },
    { type: 'para', zh: '再往西三十里，有座山叫瞻诸山，山的南面多金属，㴬水从这里发源，向东南流入洛水；少水从山的北面发源，向东流入穀水。', en: 'Thirty li west is Mount Zhu Zhu, with much gold on its south face. The Xie River flows southeast into the Luo; the Shao River flows from its north face east into the Gu waters.' },
    { type: 'para', zh: '再往西三十里，有座山叫娄涿山，没有花草树木，多金属和玉石。瞻水从山的南面发源，向东流入洛水；陂水从山的北面发源，向北流入穀水，水中多茈石和带花纹的石头。', en: 'Thirty li west is Mount Louzhuo, with no plants and much gold and jade. The Zhan River flows from its south face east into the Luo; the Bei River flows from its north face into the Gu waters, containing many purple and patterned stones.' },
    { type: 'para', zh: '再往西四十里，有座山叫白石山。惠水从山的南面发源，向南流入洛水，水中多水晶。涧水从山的北面发源，向西北流入穀水，水中多麋石和櫨丹。', en: 'Forty li west is Mount Baishi. The Hui River flows from its south face into the Luo, containing much water jade. The Jian River flows from its north face northwest into the Gu waters, containing much mi stone and ludan.' },
    { type: 'para', zh: '再往西五十里，有座山叫穀山，山上多构树，山下多桑树。爽水从这里发源，向西北流入穀水，水中多碧绿石。', en: 'Fifty li west is Mount Gu, with much paper mulberry above and mulberry below. The Shuang River flows northwest into the Gu waters, containing much blue green.' },
    { type: 'para', zh: '再往西七十二里，有座山叫密山，山的南面多玉，山的北面多铁。豪水从这里发源，向南流入洛水，水中多旋龟，长着鸟的头、鳖的尾巴，叫声像劈木头。没有花草树木。', en: 'Seventy-two li west is Mount Mi, with jade on its south face and iron on its north. The Hao River flows south into the Luo, containing many xuan turtles with bird heads and turtle tails, whose cry is like splitting wood. No plants.' },
    { type: 'para', zh: '再往西一百里，有座山叫长石山，没有花草树木，多玉。山的西面有个山谷叫共谷，谷中多竹子。共水从这里发源，向西南流入洛水，水中多鸣石。', en: 'One hundred li west is Mount Changshi, with no plants and much jade. A valley called Gonggu to its west has much bamboo. The Gong River flows southwest into the Luo, containing much ming stone.' },
    { type: 'para', zh: '再往西一百四十里，有座山叫傅山，没有花草树木，多瑶、碧等美玉。厌染水从山的南面发源，向南流入洛水，水中多人鱼。山的西面有一片树林叫墦冢。穀水从这里发源，向东流入洛水，水中多㻒玉。', en: 'One hundred forty li west is Mount Fu, with no plants and much jasper. The Yanran River flows from its south face into the Luo, containing many human fish. A forest called Fanzhong lies to its west. The Gu River flows east into the Luo, containing much xuan jade.' },
    { type: 'para', zh: '再往西五十里，有座山叫橐山，山中多樗树和𣖾树，山的南面多金属和玉石，山的北面多铁，多萧草。橐水从这里发源，向北流入黄河。水中多脩辟鱼，形状像青蛙，嘴是白色的，叫声像猫头鹰，吃了它可以治白癣。', en: 'Fifty li west is Mount Tuo, with many chinaberry and zhi trees, gold and jade on its south face, iron and much xiao on its north. The Tuo River flows north into the Yellow River, containing many xiupi fish shaped like frogs with white beaks, whose cry is like an owl\'s—eating them cures white ringworm.' },
    { type: 'para', zh: '再往西九十里，有座山叫常烝山，没有花草树木，多垩土。潐水从这里发源，向东北流入黄河，水中多苍玉。菑水从这里发源，向北流入黄河。', en: 'Ninety li west is Mount Changzheng, with no plants and much chalk. The Jiao River flows northeast into the Yellow River, containing much blue jade. The Zi River flows north into the Yellow River.' },
    { type: 'para', zh: '再往西九十里，有座山叫夸父山，山中多棕榈和楠木，多小竹，野兽多是㸲牛和羬羊，鸟类多是锦鸡，山的南面多玉，山的北面多铁。山的北面有一片树林叫桃林，方圆三百里，林中多马。湖水从这里发源，向北流入黄河，水中多㻒玉。', en: 'Ninety li west is Mount Kuafu, with much palm and nanmu and bamboo arrows, zong cattle and qian sheep as beasts, pheasants as birds, jade on its south face and iron on its north. A forest called Taolin to its north is three hundred li square, with much horses. The Hu River flows north into the Yellow River, containing much xuan jade.' },
    { type: 'para', zh: '再往西九十里，有座山叫阳华山，山的南面多金属和玉石，山的北面多青雄黄，草多是藷藇和苦辛，形状像橚草，果实像瓜，味道酸甜，吃了它可以治疟疾。杨水从这里发源，向西南流入洛水，水中多人鱼。门水从这里发源，向东北流入黄河，水中多玄䃤石。𦁎姑水从山的北面发源，向东流入门水，山上多铜。门水从黄河分出，流经七百九十里流入洛水。', en: 'Ninety li west is Mount Yanghua, with gold and jade on its south face, blue realgar on its north, much shuyu and bitter xin grass shaped like xu, with melon-like fruit tasting sour-sweet—eating it cures malaria. The Yang River flows southwest into the Luo, containing many human fish. The Men River flows northeast into the Yellow River, containing much black stone. The Qigu River flows from its north face into the Men waters, with much copper above. The Men River flows from the Yellow River, 790 li into the Luo.' },
    { type: 'para', zh: '縞羝山山系，从平逢山到阳华山，总共有十四座山，绵延七百九十里。其中有座山是岳，在第六个月份祭祀它，按照祭祀各岳的礼仪，天下就会安宁。', en: 'In all, the Gaodi Mountains from Mount Pingfeng to Mount Yanghua comprise fourteen peaks spanning 790 li. The sacred mountain is among them, sacrificed to in the sixth month following the rites of the sacred mountains—then the world is at peace.' },
    { type: 'heading', zh: '中次七经', en: 'Central Mountains VII' },
    { type: 'para', zh: '中次七经记载的苦山山系，第一座山叫休舆山。山上有一种石头，名叫帝台之棋，呈五色且有花纹，形状像鹌鹑蛋。帝台石用来向百神祈祷，佩戴它可以防蛊毒。山中有一种草，形状像蓍草，叶子是红色的，根部丛生，名叫夙条，可以做箭杆。', en: 'The seventh Central Mountains, the Bitter Mountains, begin at Mount Xiuyu. A stone called the Emperor Tai\'s chess lies above—five-colored with patterns, like quail eggs. The Emperor Tai\'s stone is used to pray to all gods; eating it prevents poison. A grass called sutiao, shaped like shi grass with red leaves and clustered roots, can be used for arrow shafts.' },
    { type: 'para', zh: '往东三百里，有座山叫鼓钟山，是帝台设宴招待百神的地方。山中有一种草，茎是方形的，开黄色的花，叶子是圆形的且三片为一组，名字叫焉酸，可以做毒药。山上多粗磨石，山下多细磨石。', en: 'Three hundred li east is Mount Guzhong, where the Emperor Tai feasts all gods. A grass called yansuan, with square stems, yellow flowers and round leaves in threes, can be used as poison. There are many whetstones above and grindstones below.' },
    { type: 'para', zh: '再往东二百里，有座山叫姑媱山。天帝的女儿死在这里，名字叫女尸，死后化成了䔄草，叶子成簇生长，开黄色的花，果实像菟丘，吃了它就能让人变得妩媚可爱。', en: 'Two hundred li east is Mount Guyao. The Emperor\'s daughter died here, called Nüshi, and transformed into yaocao—its leaves grow in clusters, its flowers are yellow, and its fruit is like tuqiu; eating it makes one charming to others.' },
    { type: 'para', zh: '再往东二十里，有座山叫苦山。山中有一种野兽，名字叫山膏，形状像野猪，红得像丹火，喜欢骂人。山上有一种树，名叫黄棘，开黄色的花，叶子是圆形的，果实像兰花。吃了它可以避孕。山中有一种草，叶子是圆形的，没有茎，开红色的花，不结果实，名字叫无条，吃了它可以治颈肿病。', en: 'Twenty li east is Mount Ku. A beast called the shangao, shaped like a zhu and red as cinnabar fire, is good at cursing. A tree called huangji above has yellow flowers and round leaves, with fruit like orchid—eating it prevents pregnancy. A grass called wutiao, with round leaves and no stems, red flowers and no fruit—eating it prevents goiter.' },
    { type: 'para', zh: '再往东二十七里，有座山叫堵山，神天愚住在这里，这里常有奇怪的风雨。山上有一种树，名叫天楄，茎是方形的，形状像葵，吃了它可以治噎塞。', en: 'Twenty-seven li east is Mount Du, where the god Tianyu dwells, with much strange wind and rain. A tree called tianbian above, with square stems and sunflower-like shape—eating it prevents choking.' },
    { type: 'para', zh: '再往东五十二里，有座山叫放皋山。明水从这里发源，向南流入伊水，水中多苍玉。山中有一种树，叶子像槐树叶，开黄色的花，不结果实，名字叫蒙木，吃了它可以治迷惑。山中有一种野兽，形状像蜜蜂，尾巴分叉，舌头是反的，喜欢鸣叫，名字叫文文。', en: 'Fifty-two li east is Mount Fanggao. The Ming River flows south into the Yi waters, containing much blue jade. A tree called mengmu, with scholar-tree leaves, yellow flowers and no fruit—eating it prevents confusion. A beast called wenwen, shaped like a bee with a branched tail and reversed tongue, is good at calling.' },
    { type: 'para', zh: '再往东五十七里，有座山叫大𩇵山，多㻬琈玉和麋玉。山中有一种草，叶子像榆树叶，茎是方形的，根部有青色斑纹，名字叫牛伤，根部有青色花纹，吃了它可以治昏厥，还可以防御兵器。山的南面有狂水发源，向西南流入伊水，水中多三足龟，吃了它可以治浮肿，预防大病。', en: 'Fifty-seven li east is Mount Dayou, with much turou jade and mi jade. A grass called niushang, with elm-like leaves, square stems and blue wounds, has blue-patterned roots—eating it prevents fainting and wards off weapons. The Kuang River flows from its south face southwest into the Yi waters, containing many three-legged turtles—eating them prevents major illness and cures swelling.' },
    { type: 'para', zh: '再往东七十里，有座山叫半石山。山上有一种草，名叫嘉荣，生长后就会抽穗开花，高一丈多，叶子是红色的，开黄色的花，只开花不结果，吃了它可以不怕打雷。来需水从山的南面发源，向西流入伊水，水中多鯩鱼，身上有黑色斑纹，形状像鲫鱼，吃了它可以治失眠。合水从山的北面发源，向北流入洛水，水中多鰧鱼，形状像鳜鱼，住在水边的洞穴中，身上有青色斑纹，尾巴是红色的，吃了它可以治痈肿和瘘管。', en: 'Seventy li east is Mount Banshi. A grass called jiarong grows and flowers there, over a zhang tall, with red leaves and yellow flowers, blooming without fruit—eating it prevents thunder. The Laixu River flows from its south face west into the Yi waters, containing many lun fish with black patterns, shaped like crucian carp—eating them prevents sleep. The He River flows from its north face into the Luo, containing many tang fish shaped like mandarin fish, dwelling in culverts, with blue patterns and red tails—eating them prevents abscesses and cures fistula.' },
    { type: 'para', zh: '再往东五十里，有座山叫少室山，各种草木生长茂盛，如同粮仓。山上有一种树，名叫帝休，叶子像杨树叶，树枝向五个方向分叉，开黄色的花，结黑色的果实，吃了它可以治愤怒。山上多玉，山下多铁。休水从这里发源，向北流入洛水，水中多䱱鱼，形状像飞鼠，爪子很长，脚是白色的且成对，吃了它可以防蛊毒、防御兵器。', en: 'Fifty li east is Mount Shaoshi, with all plants and trees forming granaries. A tree called dixiu above has poplar-like leaves, five branches, yellow flowers and black fruit—eating it prevents anger. There is much jade above and iron below. The Xiu River flows north into the Luo, containing many ti fish shaped like flying lemurs with long spurs, with white feet in pairs—eating them prevents poison and wards off weapons.' },
    { type: 'para', zh: '再往东三十里，有座山叫泰室山。山上有一种树，叶子像梨树叶，纹理是红色的，名字叫栯木，吃了它可以治嫉妒。山中有一种草，形状像𦬸草，开白色的花，结黑色的果实，光泽像蘡薁葡萄，名字叫䔄草，吃了它可以治噩梦。山上多美石。', en: 'Thirty li east is Mount Taishi. A tree called yumu above has pear-like leaves with red grain—eating it prevents jealousy. A grass called yaocao, shaped like xuan, with white flowers and black fruit, glossy like yingyu grapes—eating it prevents nightmares. There is much fine stone above.' },
    { type: 'para', zh: '再往北三十里，有座山叫讲山，山上多玉、柘树和柏树。山中有一种树，名叫帝屋，叶子像花椒叶，刺是反向的，果实是红色的，可以防御凶邪。', en: 'Thirty li north is Mount Jiang, with much jade, hackberry and cypress. A tree called diwu, with pepper-like leaves, reversed thorns and red fruit—it wards off evil.' },
    { type: 'para', zh: '再往北三十里，有座山叫婴梁山，山上多苍玉，下临玄石。', en: 'Thirty li north is Mount Yingliang, with much blue jade above, standing over black stone.' },
    { type: 'para', zh: '再往东三十里，有座山叫浮戏山。山中有一种树，叶子像樗树叶，果实是红色的，名叫亢木，吃了它可以防蛊毒。汜水从这里发源，向北流入黄河。山的东面有个山谷，因此叫蛇谷，谷中多少辛。', en: 'Thirty li east is Mount Fuxi. A tree called kangmu, with chinaberry-like leaves and red fruit—eating it prevents poison. The Si River flows north into the Yellow River. A valley to its east is called Snake Valley, with much du xin.' },
    { type: 'para', zh: '再往东四十里，有座山叫少陉山。山中有一种草，名叫𦱌草，叶子像葵叶，茎是红色的，开白色的花，果实像蘡薁葡萄，吃了它可以治愚蠢。器难水从这里发源，向北流入役水。', en: 'Forty li east is Mount Shaoxing. A grass called jiancao, with sunflower-like leaves, red stems, white flowers and fruit like yingyu grapes—eating it prevents foolishness. The Qinan River flows north into the Yi waters.' },
    { type: 'para', zh: '再往东南十里，有座山叫太山。山中有一种草，名叫棃，叶子像荻叶，开红色的花，可以治痈疽。太水从山的南面发源，向东南流入役水；承水从山的北面发源，向东北流入役水。', en: 'Ten li southeast is Mount Tai. A grass called li, shaped like miscanthus with red flowers—it cures abscesses. The Tai River flows from its south face southeast into the Yi waters; the Cheng River flows from its north face northeast into the Yi.' },
    { type: 'para', zh: '再往东二十里，有座山叫末山，山上多红铜。末水从这里发源，向北流入役水。', en: 'Twenty li east is Mount Mo, with much red gold above. The Mo River flows north into the Yi.' },
    { type: 'para', zh: '再往东二十五里，有座山叫役山，山上多白金和铁。役水从这里发源，向北流入黄河。', en: 'Twenty-five li east is Mount Yi, with much white gold and iron. The Yi River flows north into the Yellow River.' },
    { type: 'para', zh: '再往东三十五里，有座山叫敏山。山上有一种树，形状像荆条，开白色的花，结红色的果实，名叫葪柏，吃了它可以治怕冷。山的南面多㻬琈玉。', en: 'Thirty-five li east is Mount Min. A tree called jibai above, shaped like vitex with white flowers and red fruit—eating it prevents cold. There is much turou jade on its south face.' },
    { type: 'para', zh: '再往东三十里，有座山叫大騩山，山的北面多铁、美玉和青垩。山中有一种草，形状像蓍草，但有细毛，开青色的花，结白色的果实，名字叫𦵧，吃了它可以延年益寿、治腹部疾病。', en: 'Thirty li east is Mount Dagui, with iron, fine jade and blue chalk on its north face. A grass called yao, shaped like shi grass with bristles, blue flowers and white fruit—eating it prevents early death and cures abdominal disease.' },
    { type: 'para', zh: '苦山山系，从休舆山到大騩山，总共有十九座山，绵延一千一百八十四里。其中十六位山神都长着猪的身体、人的面孔。祭祀时用一只纯色的羊作祭品，用一块藻玉埋入地下。苦山、少室山、泰室山都是陵冢，祭祀时用太牢（牛、羊、猪三牲齐全），用吉玉作祭品。这些山神都长着人的面孔和三个头。其余的山神都是猪身人面。', en: 'In all, the Bitter Mountains from Mount Xiuyu to Mount Dagui comprise nineteen peaks spanning 1,184 li. Their sixteen spirits all have pig bodies and human faces. For the sacrifice, a pure ram is used for the offering, with one algae jade buried for the infant. Ku, Shaoshi and Taishi are all tombs—for their sacrifice, the full set of livestock is used with the infant in auspicious jade. Their spirits have human faces with three heads. The rest are all pig-bodied with human faces.' },
    { type: 'heading', zh: '中次八经', en: 'Central Mountains VIII' },
    { type: 'para', zh: '中次八经记载的荆山山系，第一座山叫景山，山上多金属和玉石，树木多是楸树和檀树。雎水从这里发源，向东南流入长江，水中多丹砂和带花纹的鱼。', en: 'The eighth Central Mountains, the Jing Mountains, begin at Mount Jing, with gold and jade above and catalpa and sandalwood trees. The Ju River flows southeast into the Yangtze, containing much cinnabar and many patterned fish.' },
    { type: 'para', zh: '往东北一百里，有座山叫荆山，山的北面多铁，山的南面多赤铜，山中多牦牛、豹子和老虎，树木多是松树和柏树，草多是竹子，多橘树和柚树。漳水从这里发源，向东南流入雎水，水中多黄金和鲛鱼，野兽多是山驴和麋鹿。', en: 'One hundred li northeast is Mount Jing, with iron on its north face, red copper on its south, many yaks, leopards and tigers, pines and cypresses, much bamboo, oranges and pomelos. The Zhang River flows southeast into the Ju, containing much gold, many sharks, and many white deer.' },
    { type: 'para', zh: '再往东北一百五十里，有座山叫骄山，山上多玉，山下多青雘，树木多是松树和柏树，多桃枝竹。神𧕛围住在这里，长着人的面孔、羊的角、老虎的爪子，经常在雎水和漳水的深潭中游玩，出入时有光亮。', en: 'One hundred fifty li northeast is Mount Jiao, with jade above and azurite below, pines and cypresses and many peach branches with hooked tips. The deity Weiwei dwells here—human-faced with ram horns and tiger claws, constantly swimming in the depths of Ju and Zhang, emerging and entering with light.' },
    { type: 'para', zh: '再往东北一百二十里，有座山叫女几山，山上多玉，山下多黄金，野兽多是豹子和老虎，多山驴、麋鹿、麖鹿和麂子，鸟类多是白鷮、野鸡和鸩鸟。', en: 'One hundred twenty li northeast is Mount Nüji, with jade above and gold below, tigers, leopards, white deer, mi and muntjac as beasts, and white pheasants, pheasants and poisonous birds.' },
    { type: 'para', zh: '再往东北二百里，有座山叫宜诸山，山上多金属和玉石，山下多青雘。洈水从这里发源，向南流入漳水，水中多白玉。', en: 'Two hundred li northeast is Mount Yizhu, with gold and jade above and azurite below. The Wei River flows south into the Zhang, containing much white jade.' },
    { type: 'para', zh: '再往东北三百五十里，有座山叫纶山，山中多梓树和楠木，多桃枝竹，多山楂、橘树和柚树，野兽多是山驴、麈鹿、羚羊和㚟。', en: 'Three hundred fifty li northeast is Mount Lun, with catalpa and nanmu, many peach branches, jujubes, oranges and pomelos, and white deer, antelopes and xiao as beasts.' },
    { type: 'para', zh: '再往东二百里，有座山叫陆䣀山，山上多㻬琈玉，山下多垩土，树木多是杻树和橿树。', en: 'Two hundred li east is Mount Lu\'ang, with turou jade above, chalk below, and oak and zhen trees.' },
    { type: 'para', zh: '再往东一百三十里，有座山叫光山，山上多碧玉，山下多树木。神计蒙住在这里，长着人的身体、龙的头，经常在漳水的深潭中游玩，出入时必有狂风暴雨。', en: 'One hundred thirty li east is Mount Guang, with much jasper above and many trees below. The deity Jimeng dwells here—human-bodied with a dragon head, constantly swimming in the Zhang depths, with wind and rain when emerging or entering.' },
    { type: 'para', zh: '再往东一百五十里，有座山叫岐山，山的南面多赤铜，山的北面多白银，山上多金属和玉石，山下多青雘，林中多樗树。神涉𧕛住在这里，长着人的身体、方形的面孔和三只脚。', en: 'One hundred fifty li east is Mount Qi, with red copper on its south face, white silver on its north, gold and jade above, azurite below, and many chinaberry trees in its forest. The deity Shewei dwells here—human-bodied with a square face and three feet.' },
    { type: 'para', zh: '再往东一百三十里，有座山叫铜山，山上多金、银和铁，树木多是构树、柞树、山楂、橘树和柚树，野兽多是犳。', en: 'One hundred thirty li east is Mount Tong, with gold, silver and iron above, and paper mulberry, oak, jujube, orange and pomelos, with many tao beasts.' },
    { type: 'para', zh: '再往东北一百里，有座山叫美山，野兽多是犀牛、山驴、麈鹿、野猪和鹿，山上多金属，山下多青雘。', en: 'One hundred li northeast is Mount Mei, with rhinoceros cattle, white deer, pigs and deer as beasts, gold above and azurite below.' },
    { type: 'para', zh: '再往东北一百里，有座山叫大尧山，山中多松树和柏树、梓树和桑树、机树，草多是竹子，野兽多是豹子、老虎、羚羊和㚟。', en: 'One hundred li northeast is Mount Dayao, with pines and cypresses, catalpa and mulberry, ji trees, much bamboo, and tigers, leopards, antelopes and xiao as beasts.' },
    { type: 'para', zh: '再往东北三百里，有座山叫灵山，山上多金属和玉石，山下多青雘，树木多是桃树、李树、梅树和杏树。', en: 'Three hundred li northeast is Mount Ling, with gold and jade above, azurite below, and peach, plum, apricot and cherry trees.' },
    { type: 'para', zh: '再往东北七十里，有座山叫龙山，山中多寓木，山上多碧玉，山下多赤锡，草多是桃枝竹。', en: 'Seventy li northeast is Mount Long, with many yu trees, jasper above, red tin below, and many peach branches with hooked tips.' },
    { type: 'para', zh: '再往东南五十里，有座山叫衡山，山中多寓木、构树和柞树，多黄垩和白垩。', en: 'Fifty li southeast is Mount Heng, with yu trees, paper mulberry and oaks, and much yellow and white chalk.' },
    { type: 'para', zh: '再往东南七十里，有座山叫石山，山上多金属，山下多青雘，多寓木。', en: 'Seventy li southeast is Mount Shi, with gold above, azurite below and many yu trees.' },
    { type: 'para', zh: '再往南一百二十里，有座山叫若山，山上多㻬琈玉、赭石、邽石，多寓木和柘树。', en: 'One hundred twenty li south is Mount Ruo, with turou jade, ochre, gui stones, yu trees and hackberry trees.' },
    { type: 'para', zh: '再往东南一百二十里，有座山叫彘山，多美石，多柘树。', en: 'One hundred twenty li southeast is Mount Zhi, with much beautiful stone and many hackberry trees.' },
    { type: 'para', zh: '再往东南一百五十里，有座山叫玉山，山上多金属和玉石，山下多碧玉和铁，树木多是柏树。', en: 'One hundred fifty li southeast is Mount Yu, with gold and jade above, jasper and iron below, and many cypress trees.' },
    { type: 'para', zh: '再往东南七十里，有座山叫讙山，山中多檀树、封石和白金。郁水从山上发源，从山下流过，水中多磨刀石和粗磨石。', en: 'Seventy li southeast is Mount Huan, with sandalwood trees, feng stone and white tin. The Yu River flows above and below, containing many whetstones and grindstones.' },
    { type: 'para', zh: '再往东北一百五十里，有座山叫仁举山，山中多构树和柞树，山的南面多赤铜，山的北面多赭石。', en: 'One hundred fifty li northeast is Mount Renju, with paper mulberry and oaks, red copper on its south face and ochre on its north.' },
    { type: 'para', zh: '再往东五十里，有座山叫师每山，山的南面多磨刀石和粗磨石，山的北面多青雘，树木多是柏树、檀树和柘树，草多是竹子。', en: 'Fifty li east is Mount Shimei, with whetstones and grindstones on its south face, azurite on its north, and cypress, sandalwood and hackberry trees with much bamboo.' },
    { type: 'para', zh: '再往东南二百里，有座山叫琴鼓山，山中多构树、柞树、花椒和柘树，山上多白银，山下多洗石，野兽多是野猪、鹿和白犀牛，鸟类多是鸩鸟。', en: 'Two hundred li southeast is Mount Qingu, with paper mulberry, oak, pepper and hackberry trees, white silver above, wash stones below, pigs, deer and white rhinos as beasts, and poisonous birds as birds.' },
    { type: 'para', zh: '荆山山系，从景山到琴鼓山，总共有二十三座山，绵延二千八百九十里。这些山的山神都长着鸟的身体、人的面孔。祭祀时用一只公鸡作牺牲祈祷并埋入地下，用一块藻珪，用稻米作祭品。骄山是一座陵冢，祭祀时用美酒、少牢（羊和猪）祈祷并埋入地下，用一块玉璧作祭品。', en: 'In all, the Jing Mountains from Mount Jing to Mount Qingu comprise twenty-three peaks spanning 2,890 li. Their spirits all have bird bodies and human faces. For the sacrifice: a rooster is used for prayer and burial, one algae gui, with millet for grain. Jiao Mountain is the tomb—its sacrifice uses wine, the full set of livestock for prayer and burial, with infant fur and one bi.' },
    { type: 'heading', zh: '中次九经', en: 'Central Mountains IX' },
    { type: 'para', zh: '中次九经记载的岷山山系，第一座山叫女几山，山上多石涅，树木多是杻树和橿树，草多是菊和𦬸。洛水从这里发源，向东流入长江，水中多雄黄，野兽多是老虎和豹子。', en: 'The ninth Central Mountains, the Min Mountains, begin at Mount Nüji, with much graphite above, oak and zhen trees, and chuan xuan grass. The Luo River flows east into the Yangtze, containing much realgar, with tigers and leopards as beasts.' },
    { type: 'para', zh: '再往东北三百里，有座山叫岷山。江水从这里发源，向东北流入大海，水中多优质的龟和扬子鳄，山上多金属和玉石，山下多白银，树木多是梅树和棠树，野兽多是犀牛、大象和夔牛，鸟类多是翰鸟和锦鸡。', en: 'Three hundred li northeast is Mount Min. The Yangtze River flows northeast into the sea, containing many fine turtles, alligators, gold and jade above, white silver below, plum and tang trees, rhinoceros, elephants and kui cattle as beasts, and han and pheasant birds.' },
    { type: 'para', zh: '再往东北一百四十里，有座山叫崃山。江水从这里发源，向东流入长江，山的南面多黄金，山的北面多麋鹿和麈鹿，树木多是檀树和柘树，草多是䪥和韭菜，多芍药和空夺。', en: 'One hundred forty li northeast is Mount Lai. The Yangtze River flows east into the Yangtze, with much gold on its south face, elk and deer on its north, sandalwood and hackberry trees, much chive grass, and medicines and kongduo.' },
    { type: 'para', zh: '再往东一百五十里，有座山叫崌山。江水从这里发源，向东流入长江，水中多怪蛇和䲀鱼，树木多是楢树和杻树、梅树和梓树，野兽多是夔牛、羚羊、㚟、犀牛和兕。山中有一种鸟，形状像猫头鹰，身体是红色的，头是白色的，名字叫窃脂，可以防御火灾。', en: 'One hundred fifty li east is Mount Ju. The Yangtze River flows east into the great Yangtze, containing many strange snakes, chi fish, yu and oak trees, plum and catalpa trees, kui cattle, antelopes, xiao, rhinoceros and buffalo as beasts. A bird called the qiezhi, shaped like an owl with a red body and white head, wards off fire.' },
    { type: 'para', zh: '再往东三百里，有座山叫高梁山，山上多垩土，山下多磨刀石和粗磨石，树木多是桃枝竹。山中有一种草，形状像葵草，开红色的花，结荚果，花萼是白色的，吃了它可以让马跑得快。', en: 'Three hundred li east is Mount Gaoliang, with chalk above, whetstones and grindstones below, and peach branches with hooked tips. A grass shaped like sunflowers with red flowers, pod fruit and white calyx can make horses run.' },
    { type: 'para', zh: '再往东四百里，有座山叫蛇山，山上多黄金，山下多垩土，树木多是栒树和橡树，草多是嘉荣和少辛。山中有一种野兽，形状像狐狸，尾巴是白色的，耳朵很长，名字叫𤜣狼，它一出现，国内就会发生战争。', en: 'Four hundred li east is Mount She, with gold above, chalk below, xun and zhang trees, jiarong and shaoxin grass. A beast called the lang, shaped like a fox with a white tail and long ears, foretells war within the country.' },
    { type: 'para', zh: '再往东五百里，有座山叫鬲山，山的南面多金属，山的北面多白银。蒲𪈘水从这里发源，向东流入长江，水中多白玉，野兽多是犀牛、大象、熊和罴，多猿猴。', en: 'Five hundred li east is Mount Ge, with gold on its south face and white silver on its north. The Pumai River flows east into the Yangtze, containing much white jade, rhinoceros, elephants, bears and raccoon dogs as beasts, and many apes and monkeys.' },
    { type: 'para', zh: '再往东北三百里，有座山叫隅阳山，山上多金属和玉石，山下多青雘，树木多是梓树和桑树，草多是茈草。徐水从这里发源，向东流入长江，水中多丹砂。', en: 'Three hundred li northeast is Mount Yuyang, with gold and jade above, azurite below, catalpa and mulberry trees, and much purple chive grass. The Xu River flows east into the Yangtze, containing much cinnabar.' },
    { type: 'para', zh: '再往东二百五十里，有座山叫岐山，山上多白金，山下多铁。树木多是梅树和梓树、杻树和楢树。减水从这里发源，向东南流入长江。', en: 'Two hundred fifty li east is Mount Qi, with white gold above and iron below, plum and catalpa trees, and oak and yu trees. The Jian River flows southeast into the Yangtze.' },
    { type: 'para', zh: '再往东三百里，有座山叫勾檷山，山上多玉，山下多黄金，树木多是栎树和柘树，草多是芍药。', en: 'Three hundred li east is Mount Goumi, with jade above, gold below, oak and hackberry trees, and much peony.' },
    { type: 'para', zh: '再往东一百五十里，有座山叫风雨山，山上多白金，山下多石涅；树木多是棷树和椫树、杨树。宣余水从这里发源，向东流入长江，水中多蛇。野兽多是山驴、麋鹿、麈鹿、豹子和老虎，鸟类多是白鷮。', en: 'One hundred fifty li east is Mount Fengyu, with white gold above and graphite below, zhu and shan trees and poplars. The Xuanyu River flows east into the Yangtze, containing many snakes. Its beasts include white deer, deer, leopards and tigers; its birds include white pheasants.' },
    { type: 'para', zh: '再往东北二百里，有座山叫玉山，山的南面多铜，山的北面多黄金，树木多是豫章、楢树和杻树，野兽多是野猪、鹿、羚羊和㚟，鸟类多是鸩鸟。', en: 'Two hundred li northeast is Mount Yu, with copper on its south face, red gold on its north, zhang, yu and oak trees, pigs, deer, antelopes and xiao as beasts, and poisonous birds.' },
    { type: 'para', zh: '再往东一百五十里，有座山叫熊山。山中有一个洞穴，叫熊穴，经常有神人出入。夏天开启，冬天关闭；这个洞穴如果在冬天开启，就一定会有战争。山上多白玉，山下多白金，林中多樗树和柳树，草多是寇脱。', en: 'One hundred fifty li east is Mount Xiong. A cave called the Bear\'s Cave constantly emits divine people. It opens in summer and closes in winter; if this cave opens in winter, there will certainly be war. It has white jade above, white gold below, chinaberry and willow trees, and much koutuo grass.' },
    { type: 'para', zh: '再往东一百四十里，有座山叫騩山，山的南面多美玉和黄金，山的北面多铁，树木多是桃枝竹和荆棘。', en: 'One hundred forty li east is Mount Gui, with fine jade and red gold on its south face, iron on its north, and peach branches, thorns and brambles.' },
    { type: 'para', zh: '再往东二百里，有座山叫葛山，山上多黄金，山下多瑊石，树木多是山楂、橘树、柚树、楢树和杻树，野兽多是羚羊和㚟，草多是嘉荣。', en: 'Two hundred li east is Mount Ge, with red gold above, jie stone below, jujube, orange, pomelo, yu and oak trees, antelopes and xiao as beasts, and much jiarong grass.' },
    { type: 'para', zh: '再往东一百七十里，有座山叫贾超山，山的南面多黄垩，山的北面多优质赭石，树木多是山楂、橘树和柚树，山中多龙脩。', en: 'One hundred seventy li east is Mount Jiachao, with yellow chalk on its south face, fine ochre on its north, jujube, orange and pomelo trees, and much longxiu inside.' },
    { type: 'para', zh: '岷山山系，从女几山到贾超山，总共有十六座山，绵延三千五百里。这些山的山神都长着马的身体、龙的头。祭祀时用一只公鸡埋入地下，用稻米作祭品。文山、勾檷山、风雨山、騩山都是陵冢，祭祀时用美酒、少牢祭品，用一块吉玉作祭品。熊山是帝，祭祀时用美酒、太牢祭品，用一块玉璧作祭品。举行武舞，用兵器来消灾；祈祷时，用璆冕起舞。', en: 'In all, the Min Mountains from Mount Nüji to Mount Jiachao comprise sixteen peaks spanning 3,500 li. Their spirits all have horse bodies and dragon heads. For the sacrifice: one rooster is buried, with millet for grain. Wenshan, Goumi, Fengyu and Gui are all tombs—their sacrifice uses wine, the full set of livestock, with infant fur and one auspicious jade. Xiong Mountain is the emperor—its sacrifice uses wine, the full set of livestock, with one bi for the infant. Dancing with weapons dispels evil; prayer is made with qiu and mian dancing.' },
    { type: 'heading', zh: '中次十经', en: 'Central Mountains X' },
    { type: 'para', zh: '中次十经记载的山系，第一座山叫首阳山，山上多金属和玉石，没有花草树木。', en: 'The tenth Central Mountains begin at Mount Shouyang, with gold and jade and no plants.' },
    { type: 'para', zh: '再往西五十里，有座山叫虎尾山，山中多花椒和椐树、封石；山的南面多赤铜，山的北面多铁。', en: 'Fifty li west is Mount Huwei, with pepper and zhen trees, feng stone, red copper on its south face and iron on its north.' },
    { type: 'para', zh: '再往西南五十里，有座山叫繁繢山，山中多楢树和杻树，草多是枝勾草。', en: 'Fifty li southwest is Mount Fanhui, with yu and oak trees, and much branch-and-hook grass.' },
    { type: 'para', zh: '再往西南二十里，有座山叫勇石山，没有花草树木，多白金和水。', en: 'Twenty li southwest is Mount Yongshi, with no plants, much white gold and much water.' },
    { type: 'para', zh: '再往西二十里，有座山叫复州山，山中多檀树，山的南面多黄金。山中有一种鸟，形状像猫头鹰，只有一只脚，尾巴像猪尾巴，名字叫跂踵，它一出现，那个国家就会发生大瘟疫。', en: 'Twenty li west is Mount Fuzhou, with sandalwood trees and gold on its south face. A bird called the qizhong, shaped like an owl with one foot and a pig\'s tail, foretells great plagues.' },
    { type: 'para', zh: '再往西三十里，有座山叫楮山，多寓木、花椒和椐树、柘树，多垩土。', en: 'Thirty li west is Mount Chu, with yu trees, pepper and zhen trees, hackberry trees and much chalk.' },
    { type: 'para', zh: '再往西二十里，有座山叫又原山，山的南面多青雘，山的北面多铁，鸟类多是八哥。', en: 'Twenty li west is Mount Youyuan, with azurite on its south face, iron on its north, and many myna birds.' },
    { type: 'para', zh: '再往西五十里，有座山叫涿山，山中多构树、柞树和杻树，山的南面多㻬琈玉。', en: 'Fifty li west is Mount Zhuo, with paper mulberry, oak and oak trees, and turou jade on its south face.' },
    { type: 'para', zh: '再往西七十里，有座山叫丙山，山中多梓树和檀树、弞杻树。', en: 'Seventy li west is Mount Bing, with catalpa and sandalwood trees and many shen oak trees.' },
    { type: 'para', zh: '中次十经的山系，从首阳山到丙山，总共有九座山，绵延二百六十七里。这些山的山神都长着龙的身体、人的面孔。祭祀时用一只公鸡埋入地下，用五种谷物作祭品。堵山是一座陵冢，祭祀时用少牢祭品、美酒，用一块玉璧埋入地下作祭品。騩山是帝，祭祀时用美酒、太牢祭品，两位巫师跳舞，用一块玉璧作祭品。', en: 'In all, the tenth Central Mountains from Mount Shouyang to Mount Bing comprise nine peaks spanning 267 li. Their spirits all have dragon bodies and human faces. For the sacrifice: one rooster is buried, with five types of grain. Du Mountain is the tomb—its sacrifice uses the full set of livestock, wine, with infant fur and one bi buried. Gui Mountain is the emperor—its sacrifice uses wine, the full set of livestock, two shamans dancing, with one bi for the infant.' },
    { type: 'heading', zh: '中次十一经', en: 'Central Mountains XI' },
    { type: 'para', zh: '中次十一经记载的荆山山系，第一座山叫翼望山。湍水从这里发源，向东流入济水；贶水从这里发源，向东南流入汉水，水中多蛟龙。山上多松树和柏树，山下多漆树和梓树，山的南面多赤铜，山的北面多白银。', en: 'The eleventh Central Mountains, the Jing Mountains, begin at Mount Yiwang. The Tuan River flows east into the Ji River; the Kuang River flows southeast into the Han River, containing many flood dragons. There are pines and cypresses above, lacquer and catalpa trees below, red copper on its south face and silver on its north.' },
    { type: 'para', zh: '再往东北一百五十里，有座山叫朝歌山。潕水从这里发源，向东南流入荥水，水中多人鱼。山上多梓树和楠木，野兽多是羚羊和麋鹿。山中有一种草，名叫莽草，能毒死鱼。', en: 'One hundred fifty li northeast is Mount Chaoge. The Wu River flows southeast into the Xing waters, containing many human fish. There are catalpa and nanmu trees above, antelopes and deer as beasts, and a grass called mangcao that can poison fish.' },
    { type: 'para', zh: '再往东南二百里，有座山叫帝囷山，山的南面多㻬琈玉，山的北面多铁。帝囷水从山上发源，从山下流过，水中多鸣蛇。', en: 'Two hundred li southeast is Mount Diqun, with turou jade on its south face and iron on its north. The Diqun River flows above and below, with many ming snakes.' },
    { type: 'para', zh: '再往东南五十里，有座山叫视山，山上多韭菜。山中有一口井，名叫天井，夏天有水，冬天干涸。山上多桑树，多美垩、金属和玉石。', en: 'Fifty li southeast is Mount Shi, with much chive above. A well called Tianjing has water in summer and dries in winter. There is much mulberry above, and much fine chalk, gold and jade.' },
    { type: 'para', zh: '再往东南二百里，有座山叫前山，山中多槠树和柏树，山的南面多金属，山的北面多赭石。', en: 'Two hundred li southeast is Mount Qian, with zhu and cypress trees, gold on its south face and ochre on its north.' },
    { type: 'para', zh: '再往东南三百里，有座山叫丰山。山中有一种野兽，形状像猿猴，眼睛是红色的，嘴是红色的，身体是黄色的，名字叫雍和，它一出现，国家就会有大恐慌。神耕父住在这里，经常在清泠渊中游玩，出入时有光亮，他一旦出现，国家就会败亡。山中有九口钟，它们懂得在霜降时鸣响。山上多金属，山下多构树、柞树、杻树和橿树。', en: 'Three hundred li southeast is Mount Feng. A beast called the yonghe, shaped like an ape with red eyes, red beak and yellow body, brings great fear to the nation. The deity Gengfu dwells here, constantly swimming in the Qingling depths, emerging and entering with light—his appearance foretells national ruin. There are nine bells that ring with the frost. There is much gold above and paper mulberry, oak and oak trees below.' },
    { type: 'para', zh: '再往东北八百里，有座山叫兔牀山，山的南面多铁，树木多是藷芧，草多是鸡谷，根部像鸡蛋，味道酸甜，吃了它对人有益。', en: 'Eight hundred li northeast is Mount Tuchuang, with iron on its south face, shuyu trees, chicken-grain grass with roots like chicken eggs, tasting sour-sweet—eating it benefits people.' },
    { type: 'para', zh: '再往东六十里，有座山叫皮山，多垩土和赭石，树木多是松树和柏树。', en: 'Sixty li east is Mount Pi, with much chalk and ochre, and pines and cypresses.' },
    { type: 'para', zh: '再往东六十里，有座山叫瑶碧山，山中多梓树和楠木，山的北面多青雘，山的南面多白金。山中有一种鸟，形状像野鸡，经常吃蜚虫，名叫鸩。', en: 'Sixty li east is Mount Yaobi, with catalpa and nanmu trees, azurite on its north face and white gold on its south. A bird called the zhen, shaped like a pheasant and constantly eating insects, is the poisonous zhen bird.' },
    { type: 'para', zh: '再往东四十里，有座山叫支离山。济水从这里发源，向南流入汉水。山中有一种鸟，名字叫婴勺，形状像喜鹊，眼睛是红色的，嘴是红色的，身体是白色的，尾巴像勺子，叫声像在呼唤自己的名字。山中多㸲牛和羬羊。', en: 'Forty li east is Mount Zhili. The Ji River flows south into the Han River. A bird called the yingshao, shaped like a magpie with red eyes, red beak, white body and a spoon-shaped tail, has a cry like its name. There are many zong cattle and qian sheep.' },
    { type: 'para', zh: '再往东北五十里，有座山叫祑𥮐山，山上多松树、柏树、机树和桓树。', en: 'Fifty li northeast is Mount Zhiye, with pines, cypresses, ji and huan trees above.' },
    { type: 'para', zh: '再往西北一百里，有座山叫堇理山，山上多松树和柏树、优质梓树；山的北面多丹雘和金属；野兽多是豹子和老虎。山中有一种鸟，形状像喜鹊，身体是青色的，嘴是白色的，眼睛是白色的，尾巴是白色的，名字叫青耕，可以预防瘟疫，叫声像在呼唤自己的名字。', en: 'One hundred li northwest is Mount Jinli, with pines and cypresses, fine catalpa, azurite and gold on its north face, and tigers and leopards as beasts. A bird called the qinggeng, shaped like a magpie with blue body, white beak, white eyes and white tail, wards off epidemics—its cry is like its name.' },
    { type: 'para', zh: '再往东南三十里，有座山叫依軲山，山中多杻树和橿树、苴树。山中有一种野兽，形状像狗，爪子像老虎，身上有甲，名字叫獜，善于奔跑，吃了它可以治风病。', en: 'Thirty li southeast is Mount Yigu, with oak and zhen trees and much zhu. A beast called the lin, shaped like a dog with tiger claws and armor, is good at galloping—eating it prevents wind disorders.' },
    { type: 'para', zh: '再往东南三十五里，有座山叫即谷山，多美玉、黑豹、山驴、麈鹿、羚羊和㚟。山的南面多白银，山的北面多青雘。', en: 'Thirty-five li southeast is Mount Jigu, with much beautiful jade, black leopards, white deer and antelopes. There is silver on its south face and azurite on its north.' },
    { type: 'para', zh: '再往东南四十里，有座山叫鸡山，山上多优质梓树、桑树，草多是韭菜。', en: 'Forty li southeast is Mount Ji, with fine catalpa, mulberry and much chive grass.' },
    { type: 'para', zh: '再往东南五十里，有座山叫高前山，山上有一股泉水，非常寒冷清澈，是帝台的浆水，喝了它可以治心痛。山上多金属，山下多赭石。', en: 'Fifty li southeast is Mount Gaoqian, with very cold, clear water above—the Emperor Tai\'s nectar; drinking it cures heart pain. There is gold above and ochre below.' },
    { type: 'para', zh: '再往东南三十里，有座山叫游戏山，山中多杻树、橿树和构树、玉、封石。', en: 'Thirty li southeast is Mount Youxi, with oak, zhen and grain, much jade and feng stone.' },
    { type: 'para', zh: '再往东南三十五里，有座山叫从山，山上多松树和柏树，山下多竹子。从水从山上发源，从山下流过，水中多三足鳖，尾巴分叉，吃了它可以防蛊毒。', en: 'Thirty-five li southeast is Mount Cong, with pines and cypresses above and bamboo below. The Cong River flows above and below, containing many three-legged soft-shelled turtles with branched tails—eating them prevents poison.' },
    { type: 'para', zh: '再往东南三十里，有座山叫婴䃌山，山上多松树和柏树，山下多梓树和櫄树。', en: 'Thirty li southeast is Mount Yingdun, with pines and cypresses above and catalpa and chun trees below.' },
    { type: 'para', zh: '再往东南三十里，有座山叫毕山。帝苑水从这里发源，向东北流入视水，水中多水晶和蛟龙。山上多㻬琈玉。', en: 'Thirty li east is Mount Bi. The Diyuan River flows northeast into the Shi waters, containing much water jade and many flood dragons. There is much turou jade above.' },
    { type: 'para', zh: '再往东南二十里，有座山叫乐马山。山中有一种野兽，形状像兔子，红得像丹火，名字叫𤟑，它一出现，那个国家就会发生大瘟疫。', en: 'Twenty li southeast is Mount Lema. A beast called the zhi, shaped like a rabbit and red as cinnabar fire, foretells great plagues.' },
    { type: 'para', zh: '再往东南二十五里，有座山叫葴山。视水从这里发源，向东南流入汝水，水中多人鱼、蛟龙和颉。', en: 'Twenty-five li southeast is Mount Zhen. The Shi River flows southeast into the Ru waters, containing many human fish, flood dragons and xie.' },
    { type: 'para', zh: '再往东四十里，有座山叫婴山，山下多青雘，山上多金属和玉石。', en: 'Forty li east is Mount Ying, with azurite below and gold and jade above.' },
    { type: 'para', zh: '再往东三十里，有座山叫虎首山，山中多苴树和椆椐树。', en: 'Thirty li east is Mount Hushou, with much zhu and chou zhen trees.' },
    { type: 'para', zh: '再往东二十里，有座山叫婴侯山，山上多封石，山下多赤锡。', en: 'Twenty li east is Mount Yinghou, with feng stone above and red tin below.' },
    { type: 'para', zh: '再往东五十里，有座山叫大孰山。杀水从这里发源，向东北流入视水，水中多白垩。', en: 'Fifty li east is Mount Dashu. The Sha River flows northeast into the Shi waters, containing much white chalk.' },
    { type: 'para', zh: '再往东四十里，有座山叫卑山，山上多桃树、李树、苴树和梓树，多累草。', en: 'Forty li east is Mount Bei, with peach, plum, zhu and catalpa trees and much lei.' },
    { type: 'para', zh: '再往东三十里，有座山叫倚帝山，山上多玉，山下多金属。山中有一种野兽，形状像鼣鼠，耳朵是白色的，嘴是白色的，名字叫狙如，它一出现，那个国家就会发生大战。', en: 'Thirty li east is Mount Yidi, with jade above and gold below. A beast called the juru, shaped like a mole rat with white ears and white beak, foretells great wars.' },
    { type: 'para', zh: '再往东三十里，有座山叫鲵山。鲵水从山上发源，从山下流过，水中多优质白垩。山上多金属，山下多青雘。', en: 'Thirty li east is Mount Ni. The Ni River flows above and below, containing much fine chalk. There is gold above and azurite below.' },
    { type: 'para', zh: '再往东三十里，有座山叫雅山。澧水从这里发源，向东流入视水，水中多大鱼。山上多优质桑树，山下多苴树，多黄金。', en: 'Thirty li east is Mount Ya. The Li River flows east into the Shi waters, containing many large fish. There is much fine mulberry above, much zhu below and much red gold.' },
    { type: 'para', zh: '再往东五十五里，有座山叫宣山。沦水从这里发源，向东南流入视水，水中多蛟龙。山上有一棵桑树，高五十尺，树枝向四个方向分叉，叶子长一尺多，纹理是红色的，开黄色的花，花萼是青色的，名叫帝女之桑。', en: 'Fifty-five li east is Mount Xuan. The Lun River flows southeast into the Shi waters, containing many flood dragons. A mulberry tree above is fifty zhang tall, with four branches, leaves over a chi long, red grain, yellow flowers and green calyx—called the Emperor Daughter\'s Mulberry.' },
    { type: 'para', zh: '再往东四十五里，有座山叫衡山，山中多青雘、桑树，鸟类多是八哥。', en: 'Forty-five li east is Mount Heng, with much azurite, mulberry and many myna birds.' },
    { type: 'para', zh: '再往东四十里，有座山叫丰山，山中多封石、桑树和羊桃树，形状像桃树但茎是方形的，可以用来撑皮。', en: 'Forty li east is Mount Feng, with much feng stone, mulberry and yangtao trees—peach-like with square stems, usable for leather stretching.' },
    { type: 'para', zh: '再往东七十里，有座山叫妪山，山上多美玉，山下多金属，草多是鸡谷。', en: 'Seventy li east is Mount Yu, with much fine jade above, gold below, and much chicken-grain grass.' },
    { type: 'para', zh: '再往东三十里，有座山叫鲜山，山中多楢树、杻树和苴树，草多是虋冬，山的南面多金属，山的北面多铁。山中有一种野兽，形状像膜犬，嘴是红色的，眼睛是红色的，尾巴是白色的，它一出现，当地就会发生火灾，名字叫𤝻即。', en: 'Thirty li east is Mount Xian, with yu, oak and zhu trees, much men dong grass, gold on its south face and iron on its north. A beast called the feiji, shaped like a membrane dog with red beak, red eyes and white tail, foretells fire in that city.' },
    { type: 'para', zh: '再往东三十里，有座山叫章山，山的南面多金属，山的北面多美石。皋水从这里发源，向东流入丰水，水中多脆石。', en: 'Thirty li east is Mount Zhang, with gold on its south face and beautiful stones on its north. The Gao River flows east into the Feng waters, containing much brittle stone.' },
    { type: 'para', zh: '再往东二十五里，有座山叫大支山，山的南面多金属，山中多构树和柞树，但没有花草树木。', en: 'Twenty-five li east is Mount Dazhi, with gold on its south face and paper mulberry and oaks but no plants.' },
    { type: 'para', zh: '再往东五十里，有座山叫区吴山，山中多苴树。', en: 'Fifty li east is Mount Quwu, with much zhu trees.' },
    { type: 'para', zh: '再往东五十里，有座山叫声匈山，山中多构树、玉，山上多封石。', en: 'Fifty li east is Mount Shengxiong, with much grain, jade and feng stone above.' },
    { type: 'para', zh: '再往东五十里，有座山叫大騩山，山的南面多赤铜，山的北面多磨刀石。', en: 'Fifty li east is Mount Dagui, with red copper on its south face and whetstones on its north.' },
    { type: 'para', zh: '再往东十里，有座山叫踵臼山，没有花草树木。', en: 'Ten li east is Mount Zhongjiu, with no plants.' },
    { type: 'para', zh: '再往东北七十里，有座山叫历石山，山中多荆棘，山的南面多黄金，山的北面多磨刀石。山中有一种野兽，形状像野猫，头是白色的，爪子像老虎，名字叫梁渠，它一出现，那个国家就会发生大战。', en: 'Seventy li northeast is Mount Lishi, with thorns and brambles, gold on its south face and whetstones on its north. A beast called the liangqu, shaped like a badger with a white head and tiger claws, foretells great wars.' },
    { type: 'para', zh: '再往东南一百里，有座山叫求山。求水从山上发源，从山下流过，水中有优质赭石。山中多苴树和䉋竹，山的南面多金属，山的北面多铁。', en: 'One hundred li southeast is Mount Qiu. The Qiu River flows above and below, containing much fine ochre. There is much zhu and qian, gold on its south face and iron on its north.' },
    { type: 'para', zh: '再往东二百里，有座山叫丑阳山，山中多椆椐树。山中有一种鸟，形状像乌鸦，脚是红色的，名字叫䳅鵌，可以防御火灾。', en: 'Two hundred li east is Mount Chouyang, with chou zhen trees. A bird called the zhitu, shaped like a crow with red feet, wards off fire.' },
    { type: 'para', zh: '再往东三百里，有座山叫奥山，山中多柏树、杻树和橿树，山的南面多㻬琈玉。奥水从这里发源，向东流入视水。', en: 'Three hundred li east is Mount Ao, with cypresses, oak and zhen trees, and turou jade on its south face. The Ao River flows east into the Shi waters.' },
    { type: 'para', zh: '再往东三十五里，有座山叫服山，山中多苴树，山上多封石，山下多赤锡。', en: 'Thirty-five li east is Mount Fu, with much zhu, feng stone above and red tin below.' },
    { type: 'para', zh: '再往东一百一十里，有座山叫杳山，山上多嘉荣草，多金属和玉石。', en: 'One hundred ten li east is Mount Yao, with much jiarong grass and gold and jade.' },
    { type: 'para', zh: '再往东三百五十里，有座山叫几山，山中多楢树、檀树和杻树，草多是香草。山中有一种野兽，形状像猪，身体是黄色的，头是白色的，尾巴是白色的，名字叫闻𧲂，它一出现，天下就会刮大风。', en: 'Three hundred fifty li east is Mount Ji, with yu, sandalwood and oak trees and much fragrant grass. A beast called the wenlang, shaped like a pig with yellow body, white head and white tail, brings great winds under heaven.' },
    { type: 'para', zh: '荆山山系，从翼望山到几山，总共有四十八座山，绵延三千七百三十二里。这些山的山神都长着猪的身体、人的头。祭祀时用一只公鸡祈祷，用一块珪埋入地下，用五种精选谷物作祭品。禾山是帝，祭祀时用太牢祭品，祭品倒埋、毛皮朝下；用一块玉璧，用牛的数量不固定。堵山和玉山都是陵冢，都用倒埋的方式祭祀，用少牢祭品，用吉玉作祭品。', en: 'In all, the Jing Mountains from Mount Yiwang to Mount Ji comprise forty-eight peaks spanning 3,732 li. Their spirits all have pig bodies and human heads. For the sacrifice: one rooster is used for prayer, one gui is buried, with five types of refined grain. He Mountain is the emperor—its sacrifice uses the full set of livestock, offerings buried with reversed fur, with one bi and cattle not fixed. Du Mountain and Yu Mountain are tombs—both with reversed sacrifices, offerings with the full set of livestock, with infant fur and auspicious jade.' },
    { type: 'heading', zh: '中次十二经', en: 'Central Mountains XII' },
    { type: 'para', zh: '中次十二经记载的洞庭山山系，第一座山叫篇遇山，没有花草树木，多黄金。', en: 'The twelfth Central Mountains, the Dongting Mountains, begin at Mount Pianyu, with no plants and much gold.' },
    { type: 'para', zh: '再往东南五十里，有座山叫云山，没有花草树木。山中有一种桂竹，毒性很强，被它刺伤的人必死。山上多黄金，山下多㻬琈玉。', en: 'Fifty li southeast is Mount Yun, with no plants. There is a cassia bamboo so toxic that anyone wounded by it dies. There is much gold above and turou jade below.' },
    { type: 'para', zh: '再往东南一百三十里，有座山叫龟山，山中多构树、柞树和椆椐树，山上多黄金，山下多青雄黄，多扶竹。', en: 'One hundred thirty li southeast is Mount Gui, with paper mulberry, oak and chou zhen trees, gold above, blue realgar below and much fu bamboo.' },
    { type: 'para', zh: '再往东七十里，有座山叫丙山，山中多筀竹、黄金、铜和铁，没有树木。', en: 'Seventy li east is Mount Bing, with much gui bamboo, gold, copper and iron, and no trees.' },
    { type: 'para', zh: '再往东南五十里，有座山叫风伯山，山上多金属和玉石，山下多痠石和带花纹的石头、铁，树木多是柳树、杻树、檀树和构树。山的东面有一片树林叫莽浮林，中美木、鸟兽很多。', en: 'Fifty li southeast is Mount Fengbo, with gold and jade above, suan stone and patterned stone below, much iron, willow, oak, sandalwood and paper mulberry trees. A forest called Mangfu lies to its east, with much beautiful trees, birds and beasts.' },
    { type: 'para', zh: '再往东一百五十里，有座山叫夫夫山，山上多黄金，山下多青雄黄，树木多是桑树和构树，草多是竹子和鸡鼓草。神于儿住在这里，长着人的身体，双手各握着一条蛇，经常在长江的深潭中游玩，出入时有光亮。', en: 'One hundred fifty li east is Mount Fufu, with gold above, blue realgar below, mulberry and paper mulberry trees, and much bamboo and jigu grass. The deity Yu\'er dwells here—human-bodied, holding two snakes, constantly swimming in the Yangtze depths, emerging and entering with light.' },
    { type: 'para', zh: '再往东南一百二十里，有座山叫洞庭山。山上多黄金，山下多银和铁，树木多是山楂、梨树、橘树和柚树，草多是葌草、蘼芜、芍药和芎藭。天帝的两个女儿住在这里，经常在长江的深潭中游玩。澧水和沅水的风，交汇在潇水和湘水的深潭，这里位于九江之间，出入时必有狂风暴雨。这里有很多奇怪的神，形状像人却随身带着蛇，左右手各握着一条蛇。还有很多奇怪的鸟。', en: 'One hundred twenty li southeast is Mount Dongting, with gold above, silver and iron below, jujube, pear, orange and pomelo trees, and jian, miliao, peony and chuanxiong grass. The Emperor\'s two daughters dwell here, constantly swimming in the Yangtze depths. The winds of Li and Yuan meet in the depths of Xiao and Xiang—this lies between the nine rivers, emerging and entering with violent wind and rain. There are many strange gods shaped like humans carrying snakes, holding snakes in both hands, and many strange birds.' },
    { type: 'para', zh: '再往东南一百八十里，有座山叫暴山。山中多棕榈和楠木、荆棘、小竹和䉋竹、箘竹，山上多金属和玉石，山下多带花纹的石头和铁，野兽多是麋鹿和𪊨就。', en: 'One hundred eighty li southeast is Mount Bao, with palm, nanmu, thorns, bamboo arrows and jun bamboo, much gold and jade above, patterned stone and iron below, and elk, deer and jiujiu as beasts.' },
    { type: 'para', zh: '再往东南二百里，有座山叫即公山，山上多黄金，山下多㻬琈玉，树木多是柳树、杻树、檀树和桑树。山中有一种野兽，形状像乌龟，身体是白色的，头是红色的，名字叫蛫，可以防御火灾。', en: 'Two hundred li southeast is Mount Jigong, with gold above, turou jade below, willow, oak, sandalwood and mulberry trees. A beast called the gui, shaped like a turtle with a white body and red head, wards off fire.' },
    { type: 'para', zh: '再往东南一百五十九里，有座山叫尧山，山的北面多黄垩，山的南面多黄金，树木多是荆棘、柳树和檀树，草多是藷藇和𦬸。', en: 'One hundred fifty-nine li southeast is Mount Yao, with yellow chalk on its north face, gold on its south, thorns, brambles, willow and sandalwood trees, and much shuyu and xuan grass.' },
    { type: 'para', zh: '再往东南一百里，有座山叫江浮山，山上多银和磨刀石，没有花草树木，野兽多是野猪和鹿。', en: 'One hundred li southeast is Mount Jiangfu, with silver and whetstones above, no plants, and pigs and deer as beasts.' },
    { type: 'para', zh: '再往东二百里，有座山叫真陵山，山上多黄金，山下多玉，树木多是构树、柞树、柳树和杻树，草多是荣草。', en: 'Two hundred li east is Mount Zhenling, with gold above, jade below, paper mulberry, oak, willow and oak trees, and much rong grass.' },
    { type: 'para', zh: '再往东南一百二十里，有座山叫阳帝山，山中多美铜，树木多是橿树、杻树、檿树和构树，野兽多是羚羊和麝。', en: 'One hundred twenty li southeast is Mount Yangdi, with much fine copper, zhen, oak, yang and paper mulberry trees, and antelopes and musk deer as beasts.' },
    { type: 'para', zh: '再往南九十里，有座山叫柴桑山，山上多银，山下多碧玉、泠石和赭石，树木多是柳树、𦬊树、构树和桑树，野兽多是麋鹿，多白蛇和飞蛇。', en: 'Ninety li south is Mount Chaisang, with silver above, jasper below, much cold stone and ochre, willow, jing, paper mulberry and mulberry trees, elk and deer as beasts, and many white and flying snakes.' },
    { type: 'para', zh: '再往东二百三十里，有座山叫荣余山，山上多铜；山下多银，树木多是柳树和𦬊树，蛇虫多是怪蛇和怪虫。', en: 'Two hundred thirty li east is Mount Rongyu, with copper above, silver below, willow and jing trees, and many strange snakes and insects.' },
    { type: 'para', zh: '洞庭山山系，从篇遇山到荣余山，总共有十座山，绵延二千八百里。这些山的山神都长着鸟的身体、龙的头。祭祀时用一只公鸡和一头母猪，用稻米作祭品。夫夫山、即公山、尧山、阳帝山都是陵冢，祭祀时都用陈设祭品后埋入地下的方式，祈祷时用酒，用少牢祭品，用一块吉玉作祭品。洞庭山和荣余山是山神，祭祀时都用陈设祭品后埋入地下的方式，祈祷时用酒和太牢祭品，用十五块圭和璧作祭品，用五彩装饰。', en: 'In all, the Dongting Mountains from Mount Pianyu to Mount Rongyu comprise ten peaks spanning 2,800 li. Their spirits all have bird bodies and dragon heads. For the sacrifice: one rooster and one sow are used, with millet for grain. Fufu, Jigong, Yao and Yangdi are all tombs—their sacrifices are all buried, with wine for prayer, the full set of livestock for fur, and one auspicious jade for the infant. Dongting and Rongyu are mountain gods—their sacrifices are all buried, with wine and the full set of livestock, and fifteen gui and bi for the infant, adorned with five colors.' },
    { type: 'para', zh: '以上就是中经记载的群山，总共有一百九十七座山，绵延二万一千三百七十一里。', en: 'Thus the record of the Central Mountains: one hundred ninety-seven mountains in all, spanning 21,371 li.' },
    { type: 'para', zh: '天下名山，总共有五千三百七十座，这些山分布在人类居住的地方，绵延六万四千零五十六里。', en: 'In all, the famous mountains under heaven number five thousand three hundred seventy, spanning sixty-four thousand fifty-six li of inhabited land.' },
    { type: 'heading', zh: '五臧山经', en: 'The Five Treasures Mountain Classic' },
    { type: 'para', zh: '禹说：天下的名山，经过统计共有五千三百七十座，绵延六万四千零五十六里，这些都是人类居住的地方。这里所说的《五臧山经》，是因为其余的小山太多，不值得记载。天地东西长二万八千里，南北宽二万六千里，有水流出的山绵延八千里，有水流经的山绵延八千里，产铜的山有四百六十七座，产铁的山有三千六百九十座。这些是天地划分土地、种植谷物的地方，是戈矛产生的地方，是刀剑兴起的地方，有才能的人从这里获得富足，笨拙的人则感到不足。在泰山封禅、在梁父山祭祀的，共有七十二家，得失的规律都包含在这里面，这些就是国家的用度。', en: 'Yu said: The world\'s famous mountains number five thousand three hundred seventy, spanning sixty-four thousand fifty-six li of inhabited land. These are the Five Treasures—the remaining small mountains are too numerous to record. The world spans twenty-eight thousand li east to west and twenty-six thousand li north to south. Mountains from which water flows span eight thousand li; those receiving water span eight thousand li. Copper-producing mountains number four hundred sixty-seven; iron-producing mountains number three thousand six hundred ninety. These are where heaven and earth divide the soil and plant grain, where spears and halberds originate, where swords and blades arise—the capable have abundance, the clumsy have deficiency. Enfeoffed at Mount Tai and sacrificing at Liangfu, seventy-two families—the numbers of gain and loss all lie within this; these are called the state\'s resources.' },
    { type: 'para', zh: '以上就是《五臧山经》的五篇，总共一万五千五百零三个字。', en: 'Thus the Five Treasures Mountain Classic comprises five chapters, totaling fifteen thousand five hundred three characters.' },
]

export default blocks
